        $lastCommentCandidateIndex = $this->getSiblingContinuousSingleLineComment($tokens, $lastCommentIndex, true);
        if (null === $lastCommentCandidateIndex) {
            break;
        }

        $lastCommentIndex = $lastCommentCandidateIndex;
    }

