public function findAlternativeSyntaxBlockEnd(Tokens $tokens, int $index): int
{
    $this->ensureAlternativeSyntaxStateInitialized();
    $this->alternativeSyntaxState['last_start_index'] = $index;

    if (!isset($tokens[$index])) {
