            $this->alternativeSyntaxState['last_end_index'] = $index;

            return $index;
        }

        if ($this->isStartOfAlternativeSyntaxBlock($tokens, $index)) {
            $index = $this->findAlternativeSyntaxBlockEnd($tokens, $index);
        }
    }
}

